package com.mandu.liquiddialer
import androidx.compose.ui.test.*
import com.mandu.liquiddialer.data.*
import com.mandu.liquiddialer.ui.*
import kotlinx.coroutines.runBlocking
import org.junit.*
import org.junit.Assert.*
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.*
import java.io.File
@RunWith(RobolectricTestRunner::class) @Config(sdk=[34],qualifiers="w360dp-h800dp-xhdpi") @GraphicsMode(GraphicsMode.Mode.NATIVE)
class CanvasCompositionUiTest:CallCanvasUiFixture(){
 private fun open(night:Boolean=false,empty:Boolean=false){seed(night);if(!empty)CallCanvas.save(ctx,number,"",sketch);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasCompositionWorkspace(number,{})}}};await{rule.onAllNodesWithTag("composition_paper",true).fetchSemanticsNodes().isNotEmpty()}}
 private fun enable(){runBlocking{ctx.repo.set(K.canvasComposition,true)};await{LdApp.settings.value.canvasComposition}}
 private fun dialog(tag:String){rule.onNodeWithTag(tag,true).performClick();settle()}
 @After fun resetComposition(){runBlocking{ctx.repo.set(K.canvasComposition,false)}}
 @Test fun defaultOffEntryAndDirtyGuard(){show();rule.onAllNodesWithTag("canvas_composition_open",true).assertCountEquals(0);enable();await{rule.onAllNodesWithTag("canvas_composition_open",true).fetchSemanticsNodes().isNotEmpty()};rule.onNodeWithTag("canvas_composition_open",true).assertIsEnabled();stroke();rule.onNodeWithTag("canvas_composition_open",true).assertIsNotEnabled();assertEquals(sketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun stylePreviewUndoRedoThenExplicitSave(){open();click("composition_pick_0");click("composition_ink_2");click("composition_width_3");rule.onNodeWithTag("composition_state",true).assertTextEquals("Unsaved composition preview");assertEquals(sketch,CallCanvas.read(ctx,number).strokes);click("composition_undo");click("composition_redo");click("composition_save");val expected=CanvasComposition.style(sketch,setOf(0),ink=2,width=3);await{CallCanvas.read(ctx,number).strokes==expected};assertTrue(CallCanvas.read(ctx,"+441234567890").strokes.isEmpty())}
 @Test fun selectionRequiredAndDeselect(){open();rule.onNodeWithTag("composition_ink_2",true).assertIsNotEnabled();rule.onNodeWithTag("composition_duplicate_1",true).assertIsNotEnabled();click("composition_pick_0");rule.onNodeWithTag("composition_front",true).assertIsEnabled();click("composition_all");rule.onNodeWithTag("composition_count",true).assertTextEquals("3 selected / 3 strokes");click("composition_none");rule.onNodeWithTag("composition_count",true).assertTextEquals("0 selected / 3 strokes")}
 @Test fun frontBackPreservesOrderAndClearsSelection(){open();click("composition_pick_0");click("composition_front");rule.onNodeWithTag("composition_count",true).assertTextEquals("0 selected / 3 strokes");click("composition_save");val front=listOf(sketch[1],sketch[2],sketch[0]);await{CallCanvas.read(ctx,number).strokes==front};click("composition_pick_2");click("composition_back_layer");click("composition_save");await{CallCanvas.read(ctx,number).strokes==sketch}}
 @Test fun duplicateUndoRedoNoAutomaticSave(){open();click("composition_pick_0");click("composition_duplicate_1");rule.onNodeWithTag("composition_count",true).assertTextEquals("0 selected / 4 strokes");assertEquals(sketch,CallCanvas.read(ctx,number).strokes);click("composition_undo");rule.onNodeWithTag("composition_state",true).assertTextEquals("Saved canvas");click("composition_redo");click("composition_save");await{CallCanvas.read(ctx,number).strokes==CanvasComposition.duplicate(sketch,setOf(0),400,0)}}
 @Test fun refusedWholeDuplicateHasNoUndo(){seed();val edge=listOf(sketch[0].copy(points=listOf(CallCanvas.Point(0,0))),sketch[1]);CallCanvas.save(ctx,number,"",edge);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasCompositionWorkspace(number,{})}}};await{rule.onAllNodesWithTag("composition_all",true).fetchSemanticsNodes().isNotEmpty()};click("composition_all");click("composition_duplicate_0");rule.onNodeWithTag("composition_status",true).assertTextContains("whole duplicate refused",substring=true);rule.onNodeWithTag("composition_undo",true).assertIsNotEnabled();rule.onNodeWithTag("composition_save",true).assertIsNotEnabled();assertEquals(edge,CallCanvas.read(ctx,number).strokes)}
 @Test fun staleSavePreviewRetainedAndReloadConfirmed(){open();click("composition_all");click("composition_ink_2");val old=CallCanvas.read(ctx,number);val newer=listOf(sketch.first());CallCanvas.save(ctx,number,old.raw,newer);click("composition_save");await{rule.onAllNodesWithTag("composition_error",true).fetchSemanticsNodes().isNotEmpty()};assertEquals(newer,CallCanvas.read(ctx,number).strokes);rule.onNodeWithTag("composition_state",true).assertTextEquals("Unsaved composition preview");click("composition_reload");dialog("composition_keep");rule.onNodeWithTag("composition_state",true).assertTextEquals("Unsaved composition preview");click("composition_reload");dialog("composition_discard");await{rule.onAllNodesWithTag("composition_count",true).fetchSemanticsNodes().any{it.config.getOrElse(androidx.compose.ui.semantics.SemanticsProperties.Text){emptyList()}.any{it.text=="0 selected / 1 strokes"}}}}
 @Test fun corruptReadNeverClaimsEmpty(){seed();val f=File(ctx.filesDir,"call_canvas.json");f.writeText("bad canvas");rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CanvasCompositionWorkspace(number,{})}}};await{rule.onAllNodesWithTag("composition_error",true).fetchSemanticsNodes().isNotEmpty()};rule.onAllNodesWithTag("composition_empty",true).assertCountEquals(0);rule.onAllNodesWithTag("composition_save",true).assertCountEquals(0);assertEquals("bad canvas",f.readText())}
 @Test fun entryReturnReloadsSavedCompositionNoIntent(){show();enable();click("canvas_composition_open");await{rule.onAllNodesWithTag("composition_paper",true).fetchSemanticsNodes().isNotEmpty()};click("composition_pick_0");click("composition_duplicate_1");click("composition_save");await{CallCanvas.read(ctx,number).strokes.size==4};click("page_back");await{rule.onAllNodesWithTag("canvas_paper",true).fetchSemanticsNodes().isNotEmpty()};rule.onNodeWithTag("canvas_state",true).assertTextEquals("Saved · 4 strokes");assertNull(org.robolectric.Shadows.shadowOf(rule.activity).nextStartedActivity)}
 @Test fun emptyCanvasDisabled(){open(empty=true);rule.onNodeWithTag("composition_empty",true).assertExists();rule.onNodeWithTag("composition_all",true).assertIsNotEnabled();rule.onNodeWithTag("composition_save",true).assertIsNotEnabled()}
 @Test fun confirmedDiscardInCallSheet(){seed();CallCanvas.save(ctx,number,"",sketch);var closed=false;rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{Sheet({}){CanvasCompositionWorkspace(number,{closed=true},inSheet=true)}}}};await{rule.onAllNodesWithTag("composition_all",true).fetchSemanticsNodes().isNotEmpty()};click("composition_all");click("composition_ink_2");click("composition_back");dialog("composition_keep");assertFalse(closed);click("composition_back");saveDialogShot("COMPOSITION437-discard",0xff101a30);dialog("composition_discard");assertTrue(closed);assertEquals(sketch,CallCanvas.read(ctx,number).strokes)}
 @Test fun dayPaperStyleAndToolsPixels(){open();click("composition_pick_0");click("composition_ink_2");click("composition_width_3");click("composition_duplicate_1");scrollTo("composition_paper");settle();saveShot(rule,"COMPOSITION437-day-paper");scrollTo("composition_front");settle();saveShot(rule,"COMPOSITION437-day-tools");scrollTo("composition_save");settle();saveShot(rule,"COMPOSITION437-day-save")}
 @Test fun nightLargeAndSettingsPixels(){open(true);click("composition_all");click("composition_ink_3");scrollTo("composition_paper");settle();saveShot(rule,"COMPOSITION437-night-paper");scrollTo("composition_duplicate_1");settle();saveShot(rule,"COMPOSITION437-night-tools");assertTrue(SettingsFinder.all.any{it.id=="canvas-composition"&&it.route=="callcanvas"});assertFalse(LdSettings().canvasComposition);rule.runOnUiThread{rule.activity.mountTestPage{LdThemeHost{CallCanvasPage({})}}};settle();saveShot(rule,"COMPOSITION437-settings")}
}
